# --- ast_utils.py ---
cat > "$OUTPUT_DIR/ast_utils.py" <<'AST_UTILS'
"""Utilities for working with Python abstract syntax trees (wrapping :mod:`ast`)."""

import ast as _ast


def parse(source, filename="<unknown>", mode="exec"):
    if not isinstance(source, str):
        raise TypeError("source must be a str")
    if not isinstance(filename, str):
        raise TypeError("filename must be a str")
    if mode not in ("exec", "eval", "single"):
        raise ValueError("mode must be one of 'exec', 'eval', 'single'")
    return _ast.parse(source, filename=filename, mode=mode)


def unparse(node):
    return _ast.unparse(node)


def dump(node, annotate_fields=True, include_attributes=False, indent=None):
    return _ast.dump(
        node,
        annotate_fields=annotate_fields,
        include_attributes=include_attributes,
        indent=indent,
    )


def literal_eval(node_or_string):
    return _ast.literal_eval(node_or_string)


def get_docstring(node, clean=True):
    return _ast.get_docstring(node, clean=clean)


def walk(node):
    return list(_ast.walk(node))


def iter_fields(node):
    return list(_ast.iter_fields(node))


def iter_child_nodes(node):
    return list(_ast.iter_child_nodes(node))


def find_all(node, node_type):
    result = [n for n in _ast.walk(node) if isinstance(n, node_type)]
    return result


def fix_missing_locations(node):
    return _ast.fix_missing_locations(node)


def increment_lineno(node, n=1):
    if not isinstance(n, int):
        raise TypeError("n must be an int")
    return _ast.increment_lineno(node, n=n)


def copy_location(new_node, old_node):
    return _ast.copy_location(new_node, old_node)


def node_to_string(node):
    return _ast.unparse(node)
AST_UTILS

# --- tests/test_ast_utils.py ---
cat > "$OUTPUT_DIR/tests/test_ast_utils.py" <<'TEST_AST_UTILS'
import ast
import unittest

from ast_utils import (
    copy_location,
    dump,
    find_all,
    fix_missing_locations,
    get_docstring,
    increment_lineno,
    iter_child_nodes,
    iter_fields,
    literal_eval,
    node_to_string,
    parse,
    unparse,
    walk,
)


class TestAstUtils(unittest.TestCase):
    def test_parse_exec(self):
        node = parse("x = 1")
        self.assertIsInstance(node, ast.Module)

    def test_parse_eval(self):
        node = parse("1 + 2", mode="eval")
        self.assertIsInstance(node, ast.Expression)

    def test_parse_type_error(self):
        with self.assertRaises(TypeError):
            parse(123)

    def test_parse_value_error(self):
        with self.assertRaises(ValueError):
            parse("x", mode="bad")

    def test_unparse(self):
        node = parse("x = 1")
        self.assertEqual(unparse(node).strip(), "x = 1")

    def test_dump(self):
        node = parse("x = 1")
        self.assertIn("Assign", dump(node))

    def test_literal_eval(self):
        self.assertEqual(literal_eval("[1, 2, 3]"), [1, 2, 3])

    def test_get_docstring(self):
        src = 'def f():\n    """doc"""\n    pass'
        node = parse(src)
        func = node.body[0]
        self.assertEqual(get_docstring(func), "doc")

    def test_walk(self):
        node = parse("x = 1")
        self.assertTrue(any(isinstance(n, ast.Assign) for n in walk(node)))

    def test_iter_fields(self):
        node = parse("x = 1")
        fields = iter_fields(node.body[0])
        self.assertTrue(any(k == "targets" for k, _ in fields))

    def test_iter_child_nodes(self):
        node = parse("x = 1")
        children = iter_child_nodes(node)
        self.assertTrue(len(children) >= 1)

    def test_find_all(self):
        node = parse("a = 1\nb = 2")
        assigns = find_all(node, ast.Assign)
        self.assertEqual(len(assigns), 2)

    def test_fix_missing_locations(self):
        node = parse("x = 1")
        self.assertIs(fix_missing_locations(node), node)

    def test_increment_lineno(self):
        node = parse("x = 1")
        new = increment_lineno(node, 2)
        self.assertIsNotNone(new)

    def test_increment_lineno_type_error(self):
        node = parse("x = 1")
        with self.assertRaises(TypeError):
            increment_lineno(node, "a")

    def test_copy_location(self):
        n1 = ast.Assign(targets=[ast.Name(id="x", ctx=ast.Store())], value=ast.Constant(value=1))
        n2 = ast.Assign(targets=[ast.Name(id="y", ctx=ast.Store())], value=ast.Constant(value=2))
        self.assertIs(copy_location(n1, n2), n1)

    def test_node_to_string(self):
        node = parse("x = 1")
        self.assertIn("x", node_to_string(node))


if __name__ == "__main__":
    unittest.main()
TEST_AST_UTILS

# --- pickle_utils.py ---
cat > "$OUTPUT_DIR/pickle_utils.py" <<'PICKLE_UTILS'
"""Utilities for object serialization (wrapping :mod:`pickle`)."""

import pickle as _pickle
from typing import Any

_PROTOCOLS = (-1, 0, 1, 2, 3, 4, 5)


def dump(obj, file, protocol=None, *, fix_imports=True, buffer_callback=None):
    """Pickle *obj* into an open binary *file*.

    Args:
        obj: The object to serialize.
        file: A binary-mode file-like object opened for writing.
        protocol: Pickle protocol to use (defaults to ``pickle.HIGHEST_PROTOCOL``).

    Returns:
        ``None``; the object is written to *file*.

    See :func:`pickle.dump`.
    """
    return _pickle.dump(
        obj,
        file,
        protocol,
        fix_imports=fix_imports,
        buffer_callback=buffer_callback,
    )


def dumps(obj, protocol=None, *, fix_imports=True, buffer_callback=None) -> bytes:
    """Return the pickled representation of *obj* as ``bytes``.

    Args:
        obj: The object to serialize.
        protocol: Pickle protocol to use (defaults to ``pickle.HIGHEST_PROTOCOL``).

    Returns:
        The pickled bytes.

    See :func:`pickle.dumps`.
    """
    return _pickle.dumps(
        obj,
        protocol,
        fix_imports=fix_imports,
        buffer_callback=buffer_callback,
    )


def load(file, *, fix_imports=True, buffers=()) -> Any:
    """Unpickle an object from an open binary *file*.

    Args:
        file: A binary-mode file-like object opened for reading.
        fix_imports: Whether to translate ``2to3``-style pickle names.

    Returns:
        The unpickled object.

    See :func:`pickle.load`.
    """
    return _pickle.load(file, fix_imports=fix_imports, buffers=buffers)


def loads(data, *, fix_imports=True, buffers=()) -> Any:
    """Unpickle an object from a ``bytes`` buffer.

    Args:
        data: The pickled bytes.
        fix_imports: Whether to translate ``2to3``-style pickle names.

    Returns:
        The unpickled object.

    See :func:`pickle.loads`.
    """
    return _pickle.loads(data, fix_imports=fix_imports, buffers=buffers)


def pickler(file, protocol=None, *, fix_imports=True) -> _pickle.Pickler:
    """Return a :class:`pickle.Pickler` for streaming serialization.

    Args:
        file: A binary-mode file-like object opened for writing.
        protocol: Pickle protocol to use (defaults to ``pickle.HIGHEST_PROTOCOL``).

    Returns:
        A configured :class:`pickle.Pickler`.

    See :class:`pickle.Pickler`.
    """
    return _pickle.Pickler(file, protocol=protocol, fix_imports=fix_imports)


def unpickler(file, *, fix_imports=True, buffers=()) -> _pickle.Unpickler:
    """Return a :class:`pickle.Unpickler` for streaming deserialization.

    Args:
        file: A binary-mode file-like object opened for reading.
        fix_imports: Whether to translate ``2to3``-style pickle names.

    Returns:
        A configured :class:`pickle.Unpickler`.

    See :class:`pickle.Unpickler`.
    """
    return _pickle.Unpickler(file, fix_imports=fix_imports, buffers=buffers)


def is_valid_protocol(protocol) -> bool:
    """Return ``True`` if *protocol* is a valid pickle protocol number.

    Args:
        protocol: Candidate protocol value to validate.

    Returns:
        ``True`` when *protocol* is one of ``-1`` through ``5``.
    """
    return protocol in _PROTOCOLS


def validate_protocol(protocol) -> int:
    """Validate and normalize a pickle *protocol* argument.

    Args:
        protocol: A protocol number or ``None`` (defaults to highest).

    Returns:
        The validated protocol number.

    Raises:
        TypeError: If *protocol* is not an int.
        ValueError: If *protocol* is outside the supported range.
    """
    if protocol is None:
        return _pickle.HIGHEST_PROTOCOL
    if not isinstance(protocol, int) or isinstance(protocol, bool):
        raise TypeError("protocol must be an int or None")
    if protocol not in _PROTOCOLS:
        raise ValueError(f"protocol must be one of {_PROTOCOLS}, got {protocol!r}")
    return protocol
PICKLE_UTILS

# --- tests/test_pickle_utils.py ---
cat > "$OUTPUT_DIR/tests/test_pickle_utils.py" <<'TEST_PICKLE_UTILS'
"""Tests for pickle_utils."""

import io
import pickle
import unittest

from pickle_utils import (
    dump,
    dumps,
    is_valid_protocol,
    load,
    loads,
    pickler,
    unpickler,
    validate_protocol,
)


class TestPickleUtils(unittest.TestCase):
    def test_dumps_loads_roundtrip(self):
        self.assertEqual(loads(dumps({"a": [1, 2, 3]})), {"a": [1, 2, 3]})

    def test_dumps_loads_with_protocol(self):
        for protocol in range(pickle.HIGHEST_PROTOCOL + 1):
            data = dumps("hello", protocol=protocol)
            self.assertEqual(loads(data), "hello")

    def test_dump_load_with_file(self):
        buffer = io.BytesIO()
        dump({"x": 1}, buffer)
        buffer.seek(0)
        self.assertEqual(load(buffer), {"x": 1})

    def test_pickler_unpickler_streaming(self):
        buffer = io.BytesIO()
        p = pickler(buffer)
        p.dump([1, 2, 3])
        buffer.seek(0)
        u = unpickler(buffer)
        self.assertEqual(u.load(), [1, 2, 3])

    def test_validate_protocol_none_returns_highest(self):
        self.assertEqual(validate_protocol(None), pickle.HIGHEST_PROTOCOL)

    def test_validate_protocol_valid(self):
        self.assertEqual(validate_protocol(2), 2)

    def test_validate_protocol_invalid_type(self):
        with self.assertRaises(TypeError):
            validate_protocol("2")

    def test_validate_protocol_out_of_range(self):
        with self.assertRaises(ValueError):
            validate_protocol(99)

    def test_is_valid_protocol(self):
        self.assertTrue(is_valid_protocol(0))
        self.assertTrue(is_valid_protocol(pickle.HIGHEST_PROTOCOL))
        self.assertFalse(is_valid_protocol("nope"))
        self.assertFalse(is_valid_protocol(99))

    def test_dump_load_with_explicit_protocol(self):
        buffer = io.BytesIO()
        dump("abc", buffer, protocol=2)
        buffer.seek(0)
        self.assertEqual(load(buffer), "abc")


if __name__ == "__main__":
    unittest.main()
TEST_PICKLE_UTILS

# --- marshal_utils.py ---
cat > "$OUTPUT_DIR/marshal_utils.py" <<'MARSHAL_UTILS'
"""Utilities for object serialization (wrapping :mod:`marshal`)."""

import marshal
from typing import Any, Union


def dumps(obj: Any, version: int = marshal.version) -> bytes:
    """
    Serialize an object to a bytes string using the marshal module.

    Args:
        obj: The object to serialize.
        version: The marshal protocol version to use.

    Returns:
        Serialized bytes representation of obj.

    Raises:
        TypeError: If version is not an integer.
        ValueError: If version is out of range [0, marshal.version].
        ValueError: If the object cannot be marshaled by marshal.
    """
    if not isinstance(version, int):
        raise TypeError(f"version must be an int, got {type(version).__name__}")
    if version < 0 or version > marshal.version:
        raise ValueError(
            f"version must be between 0 and {marshal.version}, got {version}"
        )
    try:
        return marshal.dumps(obj, version)
    except Exception as e:
        raise ValueError(f"Failed to marshal object: {e}") from e


def loads(data: Union[bytes, bytearray, memoryview]) -> Any:
    """
    Deserialize bytes to an object using the marshal module.

    Args:
        data: Bytes data to deserialize.

    Returns:
        The deserialized object.

    Raises:
        TypeError: If data is not bytes-like.
        ValueError: If the data cannot be unmarshaled by marshal.
    """
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise TypeError(
            f"data must be bytes-like (bytes, bytearray, memoryview), "
            f"got {type(data).__name__}"
        )
    try:
        return marshal.loads(data)
    except Exception as e:
        raise ValueError(f"Failed to unmarshal data: {e}") from e


def dump(obj: Any, file: Any, version: int = marshal.version) -> None:
    """
    Serialize an object to a file-like object using the marshal module.

    Args:
        obj: The object to serialize.
        file: A file-like object with a write method that accepts bytes.
        version: The marshal protocol version to use.

    Returns:
        None.

    Raises:
        TypeError: If file is not writeable or version is not an integer.
        ValueError: If version is out of range or marshaling fails.
        AttributeError: If file lacks a write method.
    """
    if not hasattr(file, "write"):
        raise AttributeError("file must have a 'write' method")
    if not callable(file.write):
        raise TypeError("file.write must be callable")
    if not isinstance(version, int):
        raise TypeError(f"version must be an int, got {type(version).__name__}")
    if version < 0 or version > marshal.version:
        raise ValueError(
            f"version must be between 0 and {marshal.version}, got {version}"
        )
    try:
        marshal.dump(obj, file, version)
    except Exception as e:
        raise ValueError(f"Failed to marshal object to file: {e}") from e


def load(file: Any) -> Any:
    """
    Deserialize an object from a file-like object using the marshal module.

    Args:
        file: A file-like object with a read method that accepts bytes count.

    Returns:
        The deserialized object.

    Raises:
        TypeError: If file is not readable.
        ValueError: If unmarshaling fails.
        AttributeError: If file lacks a read method.
    """
    if not hasattr(file, "read"):
        raise AttributeError("file must have a 'read' method")
    if not callable(file.read):
        raise TypeError("file.read must be callable")
    try:
        return marshal.load(file)
    except Exception as e:
        raise ValueError(f"Failed to unmarshal data from file: {e}") from e


def get_version() -> int:
    """
    Get the current marshal version.

    Returns:
        The current marshal.version value.
    """
    return marshal.version
MARSHAL_UTILS

