# --- circuit_breaker_utils.py ---
cat > "$OUTPUT_DIR/circuit_breaker_utils.py" <<'CIRCUITBREAKERUTILS'
"""Circuit breaker utilities.

This module provides a :class:`CircuitBreaker` implementing the circuit breaker
resilience pattern, which wraps an operation and short-circuits calls once a
configurable failure threshold is reached. The circuit cycles through three
states:

* ``CLOSED`` — calls execute normally; failures increment the failure counter.
* ``OPEN`` — calls are rejected immediately with :class:`CircuitOpenError`.
* ``HALF_OPEN`` — a single trial call is allowed after the recovery timeout;
  success closes the circuit, failure re-opens it.

All state transitions are thread-safe. A circuit breaker is useful for failing
fast against a flaky downstream dependency instead of repeatedly waiting on
timeouts, giving the dependency time to recover.
"""

from __future__ import annotations

import threading
import time
from typing import Any, Callable, Optional, Tuple, TypeVar, Union

T = TypeVar("T")


class CircuitOpenError(RuntimeError):
    """Raised when an operation is rejected because the circuit is open."""


class CircuitBreaker:
    """A thread-safe circuit breaker that short-circuits failing operations.

    Args:
        failure_threshold: Number of consecutive failures required to open the
            circuit. Must be at least 1.
        recovery_timeout: Seconds to wait before allowing a recovery trial call
            once the circuit is open. Must be greater than 0.
        expected_exception: An exception class, or tuple of exception classes,
            that count as failures. Any other exception propagates and is not
            counted.

    Raises:
        TypeError: If ``failure_threshold`` is not an integer,
            ``recovery_timeout`` is not a number, or ``expected_exception`` is
            not an exception class or tuple of exception classes.
        ValueError: If ``failure_threshold`` is less than 1 or
            ``recovery_timeout`` is not greater than 0.
    """

    CLOSED = "closed"
    OPEN = "open"
    HALF_OPEN = "half_open"

    def __init__(
        self,
        failure_threshold: int = 5,
        recovery_timeout: float = 30.0,
        expected_exception: Union[
            type[BaseException], Tuple[type[BaseException], ...]
        ] = Exception,
    ) -> None:
        if isinstance(failure_threshold, bool) or not isinstance(failure_threshold, int):
            raise TypeError("failure_threshold must be an integer")
        if failure_threshold < 1:
            raise ValueError("failure_threshold must be at least 1")
        if isinstance(recovery_timeout, bool) or not isinstance(
            recovery_timeout, (int, float)
        ):
            raise TypeError("recovery_timeout must be a number")
        if recovery_timeout <= 0:
            raise ValueError("recovery_timeout must be greater than 0")

        if isinstance(expected_exception, type):
            expected_exceptions: Tuple[type[BaseException], ...] = (
                expected_exception,
            )
        elif isinstance(expected_exception, tuple) and all(
            isinstance(exc, type) for exc in expected_exception
        ):
            expected_exceptions = expected_exception
        else:
            raise TypeError(
                "expected_exception must be an exception class or a tuple of "
                "exception classes"
            )

        self._failure_threshold = failure_threshold
        self._recovery_timeout = float(recovery_timeout)
        self._expected_exceptions = expected_exceptions
        self._lock = threading.Lock()
        self._state = self.CLOSED
        self._failures = 0
        self._opened_at: Optional[float] = None
        self._half_open_trial = False

    @property
    def state(self) -> str:
        """Return the current circuit state (``closed``, ``open``, ``half_open``)."""
        with self._lock:
            self._maybe_transition()
            return self._state

    @property
    def failures(self) -> int:
        """Return the current consecutive failure count."""
        with self._lock:
            return self._failures

    @property
    def failure_threshold(self) -> int:
        """Return the failure threshold used to open the circuit."""
        return self._failure_threshold

    @property
    def recovery_timeout(self) -> float:
        """Return the recovery timeout in seconds."""
        return self._recovery_timeout

    def _maybe_transition(self) -> None:
        """Move an open circuit to half-open once the recovery timeout elapses."""
        if (
            self._state == self.OPEN
            and self._opened_at is not None
            and time.monotonic() - self._opened_at >= self._recovery_timeout
        ):
            self._state = self.HALF_OPEN

    def _record_failure(self) -> None:
        """Record a failed call, opening or re-opening the circuit as needed."""
        self._failures += 1
        if self._state == self.HALF_OPEN or self._failures >= self._failure_threshold:
            self._state = self.OPEN
            self._opened_at = time.monotonic()

    def _record_success(self) -> None:
        """Record a successful call, closing the circuit."""
        self._failures = 0
        self._opened_at = None
        self._state = self.CLOSED

    def can_execute(self) -> bool:
        """Return whether a call would be allowed right now.

        An open circuit that has not yet reached its recovery timeout reports
        ``False``; once the timeout elapses the circuit moves to half-open and
        reports ``True`` for a single trial call.
        """
        with self._lock:
            self._maybe_transition()
            if self._state == self.HALF_OPEN and self._half_open_trial:
                return False
            return self._state != self.OPEN

    def call(self, func: Callable[..., T], *args: Any, **kwargs: Any) -> T:
        """Execute ``func`` through the circuit breaker.

        Args:
            func: The callable to execute.
            *args: Positional arguments forwarded to ``func``.
            **kwargs: Keyword arguments forwarded to ``func``.

        Returns:
            The return value of ``func``.

        Raises:
            TypeError: If ``func`` is not callable.
            CircuitOpenError: If the circuit is open, or if a half-open trial
                call is already in progress.
        """
        if not callable(func):
            raise TypeError("func must be callable")

        with self._lock:
            self._maybe_transition()
            if self._state == self.OPEN:
                remaining = self._recovery_timeout
                if self._opened_at is not None:
                    remaining = max(
                        0.0, self._recovery_timeout - (time.monotonic() - self._opened_at)
                    )
                raise CircuitOpenError(
                    f"circuit breaker is open; retry in {remaining:.2f} seconds"
                )
            if self._state == self.HALF_OPEN:
                if self._half_open_trial:
                    raise CircuitOpenError(
                        "circuit breaker is half-open; a trial call is in progress"
                    )
                self._half_open_trial = True

        try:
            result = func(*args, **kwargs)
        except self._expected_exceptions:
            with self._lock:
                self._record_failure()
                self._half_open_trial = False
            raise
        else:
            with self._lock:
                self._record_success()
                self._half_open_trial = False
            return result

    def reset(self) -> None:
        """Reset the circuit to the closed state with zero failures."""
        with self._lock:
            self._state = self.CLOSED
            self._failures = 0
            self._opened_at = None
            self._half_open_trial = False
CIRCUITBREAKERUTILS
# --- tests/test_circuit_breaker_utils.py ---
cat > "$OUTPUT_DIR/tests/test_circuit_breaker_utils.py" <<'TESTCIRCUITBREAKERUTILS'
import threading
import time
import unittest

from circuit_breaker_utils import CircuitBreaker, CircuitOpenError


class TestCircuitBreaker(unittest.TestCase):
    def test_closed_executes_normally(self):
        breaker = CircuitBreaker(failure_threshold=3)
        calls = []

        def get_value() -> int:
            calls.append(1)
            return 42

        self.assertEqual(breaker.call(get_value), 42)
        self.assertEqual(calls, [1])
        self.assertEqual(breaker.state, CircuitBreaker.CLOSED)
        self.assertEqual(breaker.failures, 0)

    def test_opens_after_threshold(self):
        breaker = CircuitBreaker(failure_threshold=3)

        def fail() -> None:
            raise ValueError("boom")

        for _ in range(2):
            with self.assertRaises(ValueError):
                breaker.call(fail)
        self.assertEqual(breaker.state, CircuitBreaker.CLOSED)
        self.assertEqual(breaker.failures, 2)
        # Third failure opens the circuit.
        with self.assertRaises(ValueError):
            breaker.call(fail)
        self.assertEqual(breaker.state, CircuitBreaker.OPEN)
        self.assertEqual(breaker.failures, 3)

    def test_open_rejects_calls(self):
        breaker = CircuitBreaker(failure_threshold=1, recovery_timeout=60.0)

        def always_fail() -> None:
            raise ValueError("boom")

        with self.assertRaises(ValueError):
            breaker.call(always_fail)
        self.assertEqual(breaker.state, CircuitBreaker.OPEN)
        # Open circuit short-circuits without invoking func.
        called = []

        def guarded() -> str:
            called.append(1)
            return "ok"

        with self.assertRaises(CircuitOpenError):
            breaker.call(guarded)
        self.assertEqual(called, [])

    def test_can_execute_reflects_open_state(self):
        breaker = CircuitBreaker(failure_threshold=1, recovery_timeout=60.0)

        def fail() -> None:
            raise ValueError("boom")

        with self.assertRaises(ValueError):
            breaker.call(fail)
        self.assertFalse(breaker.can_execute())

    def test_half_open_allows_trial_call(self):
        breaker = CircuitBreaker(failure_threshold=1, recovery_timeout=0.05)

        def fail() -> None:
            raise ValueError("boom")

        with self.assertRaises(ValueError):
            breaker.call(fail)
        self.assertEqual(breaker.state, CircuitBreaker.OPEN)
        time.sleep(0.1)
        self.assertEqual(breaker.state, CircuitBreaker.HALF_OPEN)
        # A successful trial call closes the circuit.
        self.assertEqual(breaker.call(lambda: "ok"), "ok")
        self.assertEqual(breaker.state, CircuitBreaker.CLOSED)

    def test_half_open_failed_trial_reopens(self):
        breaker = CircuitBreaker(failure_threshold=1, recovery_timeout=0.05)

        def fail() -> None:
            raise ValueError("boom")

        with self.assertRaises(ValueError):
            breaker.call(fail)
        self.assertEqual(breaker.state, CircuitBreaker.OPEN)
        time.sleep(0.1)
        self.assertEqual(breaker.state, CircuitBreaker.HALF_OPEN)
        with self.assertRaises(ValueError):
            breaker.call(fail)
        self.assertEqual(breaker.state, CircuitBreaker.OPEN)

    def test_half_open_only_one_trial_at_a_time(self):
        breaker = CircuitBreaker(failure_threshold=1, recovery_timeout=0.05)

        with self.assertRaises(ValueError):
            breaker.call(lambda: (_ for _ in ()).throw(ValueError("boom")))
        time.sleep(0.1)
        self.assertEqual(breaker.state, CircuitBreaker.HALF_OPEN)
        trial_started = threading.Event()
        trial_release = threading.Event()

        def blocking_trial() -> str:
            trial_started.set()
            trial_release.wait()
            return "ok"

        trial_thread = threading.Thread(target=lambda: breaker.call(blocking_trial))
        trial_thread.start()
        self.assertTrue(trial_started.wait(timeout=5))
        # While a trial call is in progress, a second call is rejected.
        with self.assertRaises(CircuitOpenError):
            breaker.call(lambda: "ok")
        trial_release.set()
        trial_thread.join()
        self.assertEqual(breaker.state, CircuitBreaker.CLOSED)

    def test_expected_exception_only(self):
        breaker = CircuitBreaker(failure_threshold=1, expected_exception=ValueError)

        def type_error() -> None:
            raise TypeError("wrong type")

        # TypeError is not expected, so it propagates and does not open.
        with self.assertRaises(TypeError):
            breaker.call(type_error)
        self.assertEqual(breaker.state, CircuitBreaker.CLOSED)
        self.assertEqual(breaker.failures, 0)

    def test_reset_closes_circuit(self):
        breaker = CircuitBreaker(failure_threshold=1, recovery_timeout=60.0)

        def fail() -> None:
            raise ValueError("boom")

        with self.assertRaises(ValueError):
            breaker.call(fail)
        self.assertEqual(breaker.state, CircuitBreaker.OPEN)
        breaker.reset()
        self.assertEqual(breaker.state, CircuitBreaker.CLOSED)
        self.assertEqual(breaker.failures, 0)
        self.assertTrue(breaker.can_execute())
        self.assertEqual(breaker.call(lambda: 1), 1)

    def test_non_callable_raises(self):
        breaker = CircuitBreaker()
        with self.assertRaises(TypeError):
            breaker.call(42)  # type: ignore[arg-type]

    def test_invalid_threshold_raises(self):
        with self.assertRaises(TypeError):
            CircuitBreaker(failure_threshold="3")  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            CircuitBreaker(failure_threshold=0)

    def test_invalid_timeout_raises(self):
        with self.assertRaises(TypeError):
            CircuitBreaker(recovery_timeout="30")  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            CircuitBreaker(recovery_timeout=0)

    def test_invalid_expected_exception_raises(self):
        with self.assertRaises(TypeError):
            CircuitBreaker(expected_exception="ValueError")  # type: ignore[arg-type]

    def test_thread_safe_concurrent_failures(self):
        breaker = CircuitBreaker(failure_threshold=50)
        errors: list[BaseException] = []

        def worker() -> None:
            try:
                breaker.call(lambda: (_ for _ in ()).throw(ValueError("boom")))
            except ValueError as exc:
                errors.append(exc)

        threads = [threading.Thread(target=worker) for _ in range(50)]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join()
        self.assertEqual(len(errors), 50)
        self.assertEqual(breaker.state, CircuitBreaker.OPEN)
        self.assertEqual(breaker.failures, 50)


class TestCircuitOpenError(unittest.TestCase):
    def test_is_runtime_error(self):
        self.assertTrue(issubclass(CircuitOpenError, RuntimeError))
        err = CircuitOpenError("circuit open")
        self.assertEqual(str(err), "circuit open")


if __name__ == "__main__":
    unittest.main()
TESTCIRCUITBREAKERUTILS
# --- async_utils.py ---
cat > "$OUTPUT_DIR/async_utils.py" <<'ASYNCUTILS'
"""Asynchronous utility functions."""

from __future__ import annotations

import asyncio
from typing import Any, Awaitable, Callable, List, Optional, TypeVar

T = TypeVar("T")

__all__: List[str] = [
    "run_in_thread",
    "gather_with_timeout",
    "async_sleep",
    "retry_async",
]


async def run_in_thread(func: Callable[..., T], *args: Any, **kwargs: Any) -> T:
    """Run a synchronous function in a thread pool."""
    loop = asyncio.get_running_loop()
    return await loop.run_in_executor(None, lambda: func(*args, **kwargs))


async def gather_with_timeout(
    *coros: Awaitable[Any], timeout: Optional[float] = None
) -> List[Any]:
    """Gather multiple coroutines with an optional timeout."""
    if timeout is None:
        return await asyncio.gather(*coros)
    return await asyncio.wait_for(asyncio.gather(*coros), timeout=timeout)


async def async_sleep(seconds: float) -> None:
    """Sleep for the specified number of seconds asynchronously."""
    await asyncio.sleep(seconds)


async def retry_async(
    func: Callable[..., Awaitable[T]],
    *args: Any,
    max_attempts: int = 3,
    delay: float = 0.1,
    **kwargs: Any,
) -> T:
    """Retry an async function on exceptions."""
    last_exception: Exception = Exception("No attempts made")
    for attempt in range(max_attempts):
        try:
            return await func(*args, **kwargs)
        except Exception as exc:  # noqa: BLE001
            last_exception = exc
            if attempt < max_attempts - 1:
                await asyncio.sleep(delay)
    raise last_exception
ASYNCUTILS

# --- bit_utils.py ---
cat > "$OUTPUT_DIR/bit_utils.py" <<'BITUTILS'
"""Bitwise utility functions for working with binary representations of integers.

This module provides utilities for counting bits, manipulating individual bits,
detecting powers of two, reversing bits, and rotating bit fields. All functions
operate on non-negative integers unless otherwise noted.
"""

from __future__ import annotations

from typing import Optional

__all__: list[str] = [
    "count_set_bits",
    "is_power_of_two",
    "next_power_of_two",
    "prev_power_of_two",
    "reverse_bits",
    "rotate_left",
    "rotate_right",
    "get_bit",
    "set_bit",
    "clear_bit",
    "toggle_bit",
    "is_even",
    "is_odd",
]


def _validate_nonnegative_int(value: int, name: str = "value") -> None:
    if not isinstance(value, int) or isinstance(value, bool):
        raise TypeError(f"{name} must be an integer")
    if value < 0:
        raise ValueError(f"{name} must be non-negative")


def _validate_index(index: int) -> None:
    if not isinstance(index, int) or isinstance(index, bool):
        raise TypeError("index must be an integer")
    if index < 0:
        raise ValueError("index must be non-negative")


def _validate_positive_int(value: int, name: str = "value") -> None:
    if not isinstance(value, int) or isinstance(value, bool):
        raise TypeError(f"{name} must be an integer")
    if value <= 0:
        raise ValueError(f"{name} must be positive")


def count_set_bits(value: int) -> int:
    """Return the number of set bits (1s) in the binary representation of value.

    Args:
        value: A non-negative integer.

    Returns:
        The count of set bits.

    Raises:
        TypeError: If value is not an integer.
        ValueError: If value is negative.

    Examples:
        >>> count_set_bits(0)
        0
        >>> count_set_bits(5)  # 0b101
        2
        >>> count_set_bits(7)  # 0b111
        3
    """
    _validate_nonnegative_int(value)
    return bin(value).count("1")


def is_power_of_two(value: int) -> bool:
    """Return True if value is a power of two.

    Args:
        value: An integer.

    Returns:
        True if value is a power of two, False otherwise.

    Examples:
        >>> is_power_of_two(1)
        True
        >>> is_power_of_two(16)
        True
        >>> is_power_of_two(18)
        False
    """
    if not isinstance(value, int) or isinstance(value, bool):
        raise TypeError("value must be an integer")
    return value > 0 and (value & (value - 1)) == 0


def next_power_of_two(value: int) -> int:
    """Return the smallest power of two greater than or equal to value.

    Args:
        value: A non-negative integer.

    Returns:
        The next power of two.

    Raises:
        TypeError: If value is not an integer.
        ValueError: If value is negative.

    Examples:
        >>> next_power_of_two(0)
        1
        >>> next_power_of_two(5)
        8
        >>> next_power_of_two(16)
        16
    """
    _validate_nonnegative_int(value)
    if value == 0:
        return 1
    return 1 << (value - 1).bit_length()


def prev_power_of_two(value: int) -> int:
    """Return the largest power of two less than or equal to value.

    Args:
        value: A non-negative integer.

    Returns:
        The previous power of two, or 0 if value is 0.

    Raises:
        TypeError: If value is not an integer.
        ValueError: If value is negative.

    Examples:
        >>> prev_power_of_two(0)
        0
        >>> prev_power_of_two(5)
        4
        >>> prev_power_of_two(16)
        16
    """
    _validate_nonnegative_int(value)
    if value == 0:
        return 0
    return 1 << (value.bit_length() - 1)


def reverse_bits(value: int, width: Optional[int] = None) -> int:
    """Reverse the bits of value within the given width.

    Args:
        value: A non-negative integer.
        width: The bit width to reverse within. Defaults to the minimal width
            needed to represent value.

    Returns:
        The integer with bits reversed.

    Raises:
        TypeError: If value or width is not an integer.
        ValueError: If value is negative or width is not positive.

    Examples:
        >>> reverse_bits(0b0001, 4)
        8
        >>> reverse_bits(13, 4)  # 1101 -> 1011
        11
    """
    _validate_nonnegative_int(value)
    if width is None:
        width = value.bit_length() or 1
    _validate_positive_int(width, "width")
    result = 0
    for i in range(width):
        if (value >> i) & 1:
            result |= 1 << (width - 1 - i)
    return result


def rotate_left(value: int, shift: int, width: int) -> int:
    """Rotate the bits of value left by shift positions within width bits.

    Args:
        value: A non-negative integer.
        shift: Number of positions to rotate.
        width: The bit width to rotate within.

    Returns:
        The rotated integer.

    Raises:
        TypeError: If arguments are not integers.
        ValueError: If value is negative or width is not positive.

    Examples:
        >>> rotate_left(0b0001, 1, 4)
        2
        >>> rotate_left(0b1000, 1, 4)
        1
    """
    _validate_nonnegative_int(value)
    if not isinstance(shift, int) or isinstance(shift, bool):
        raise TypeError("shift must be an integer")
    _validate_positive_int(width, "width")
    shift %= width
    mask = (1 << width) - 1
    return ((value << shift) | (value >> (width - shift))) & mask


def rotate_right(value: int, shift: int, width: int) -> int:
    """Rotate the bits of value right by shift positions within width bits.

    Args:
        value: A non-negative integer.
        shift: Number of positions to rotate.
        width: The bit width to rotate within.

    Returns:
        The rotated integer.

    Raises:
        TypeError: If arguments are not integers.
        ValueError: If value is negative or width is not positive.

    Examples:
        >>> rotate_right(0b1000, 1, 4)
        4
        >>> rotate_right(0b0001, 1, 4)
        8
    """
    _validate_nonnegative_int(value)
    if not isinstance(shift, int) or isinstance(shift, bool):
        raise TypeError("shift must be an integer")
    _validate_positive_int(width, "width")
    shift %= width
    mask = (1 << width) - 1
    return ((value >> shift) | (value << (width - shift))) & mask


def get_bit(value: int, index: int) -> int:
    """Return the bit at index (0 = least significant bit).

    Args:
        value: A non-negative integer.
        index: The bit index to read.

    Returns:
        0 or 1.

    Raises:
        TypeError: If arguments are not integers.
        ValueError: If value is negative or index is negative.

    Examples:
        >>> get_bit(0b1010, 1)
        1
        >>> get_bit(0b1010, 2)
        0
    """
    _validate_nonnegative_int(value)
    _validate_index(index)
    return (value >> index) & 1


def set_bit(value: int, index: int) -> int:
    """Return value with the bit at index set to 1.

    Args:
        value: A non-negative integer.
        index: The bit index to set.

    Returns:
        The updated integer.

    Raises:
        TypeError: If arguments are not integers.
        ValueError: If value is negative or index is negative.

    Examples:
        >>> set_bit(0b0000, 2)
        4
    """
    _validate_nonnegative_int(value)
    _validate_index(index)
    return value | (1 << index)


def clear_bit(value: int, index: int) -> int:
    """Return value with the bit at index cleared to 0.

    Args:
        value: A non-negative integer.
        index: The bit index to clear.

    Returns:
        The updated integer.

    Raises:
        TypeError: If arguments are not integers.
        ValueError: If value is negative or index is negative.

    Examples:
        >>> clear_bit(0b1111, 1)
        13
    """
    _validate_nonnegative_int(value)
    _validate_index(index)
    return value & ~(1 << index)


def toggle_bit(value: int, index: int) -> int:
    """Return value with the bit at index flipped.

    Args:
        value: A non-negative integer.
        index: The bit index to toggle.

    Returns:
        The updated integer.

    Raises:
        TypeError: If arguments are not integers.
        ValueError: If value is negative or index is negative.

    Examples:
        >>> toggle_bit(0b1010, 1)
        8
        >>> toggle_bit(0b1010, 0)
        11
    """
    _validate_nonnegative_int(value)
    _validate_index(index)
    return value ^ (1 << index)


def is_even(value: int) -> bool:
    """Return True if value is even.

    Args:
        value: An integer.

    Returns:
        True if value is even, False otherwise.

    Examples:
        >>> is_even(4)
        True
        >>> is_even(7)
        False
    """
    if not isinstance(value, int) or isinstance(value, bool):
        raise TypeError("value must be an integer")
    return (value & 1) == 0


def is_odd(value: int) -> bool:
    """Return True if value is odd.

    Args:
        value: An integer.

    Returns:
        True if value is odd, False otherwise.

    Examples:
        >>> is_odd(4)
        False
        >>> is_odd(7)
        True
    """
    if not isinstance(value, int) or isinstance(value, bool):
        raise TypeError("value must be an integer")
    return (value & 1) == 1
BITUTILS
