        with self.assertRaises(TypeError):
            replace(Simple, x=5)  # type: ignore[arg-type]

    def test_replace_raises_on_non_dataclass(self):
        with self.assertRaises(TypeError):
            replace("not a dataclass", x=5)  # type: ignore[arg-type]

