        with self.assertRaises(TypeError):
            make_dataclass(123, [("x", int)])  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            make_dataclass("P", "not iterable")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
