class TestProgressBar(unittest.TestCase):
    def test_total_must_be_positive(self):
        with self.assertRaises(ValueError):
            ProgressBar(0)
        with self.assertRaises(ValueError):
            ProgressBar(-3)
        with self.assertRaises(ValueError):
            ProgressBar(True)

    def test_fill_and_empty_must_be_single_characters(self):
        with self.assertRaises(ValueError):
            ProgressBar(1, fill="ab")
        with self.assertRaises(ValueError):
            ProgressBar(1, empty="")

    def test_render_shows_progress(self):
        stream = io.StringIO()
        bar = ProgressBar(10, width=10, stream=stream)
        bar.update(5)
        output = stream.getvalue()
        self.assertIn("[#####-----]", output)
        self.assertIn("50%", output)
        self.assertIn("(5/10)", output)

    def test_update_out_of_range_raises_value_error(self):
        bar = ProgressBar(5, stream=io.StringIO())
        with self.assertRaises(ValueError):
            bar.update(6)
        with self.assertRaises(ValueError):
            bar.update(-1)

    def test_update_non_integer_raises_type_error(self):
        bar = ProgressBar(5, stream=io.StringIO())
        with self.assertRaises(TypeError):
            bar.update("3")

    def test_update_after_finish_is_noop(self):
        stream = io.StringIO()
        bar = ProgressBar(2, stream=stream)
        bar.finish()
        before = stream.getvalue()
        bar.update(1)
        self.assertEqual(stream.getvalue(), before)

    def test_finish_writes_final_newline(self):
        stream = io.StringIO()
        bar = ProgressBar(3, stream=stream)
        bar.finish()
        self.assertIn("\n", stream.getvalue())

    def test_context_manager_finishes(self):
        stream = io.StringIO()
        with ProgressBar(4, stream=stream) as bar:
            bar.update(2)
        self.assertTrue(bar._finished)

    def test_yields_items(self):
        stream = io.StringIO()
        result = list(progress_bar([1, 2, 3], stream=stream))
        self.assertEqual(result, [1, 2, 3])

    def test_total_inferred_from_len(self):
        stream = io.StringIO()
        result = list(progress_bar([10, 20], stream=stream))
        self.assertEqual(result, [10, 20])

    def test_iterable_without_len_requires_total(self):
        def generator():
            yield 1
            yield 2

        with self.assertRaises(ValueError):
            list(progress_bar(generator()))

    def test_increment_advances(self):
        stream = io.StringIO()
        bar = ProgressBar(3, stream=stream)
        bar.update(increment=1)
        bar.update(increment=1)
        self.assertEqual(bar._current, 2)


class TestPrompt(unittest.TestCase):
    def test_returns_entered_value(self):
        with patch("builtins.input", return_value="Alice"):
            self.assertEqual(prompt("Name"), "Alice")

    def test_returns_default_on_empty_input(self):
        with patch("builtins.input", return_value=""):
            self.assertEqual(prompt("Name", default="Guest"), "Guest")

    def test_returns_empty_string_when_no_default(self):
        with patch("builtins.input", return_value=""):
            self.assertEqual(prompt("Name"), "")

    def test_raises_eof_error_on_closed_stream(self):
        with patch("builtins.input", side_effect=EOFError):
            with self.assertRaises(EOFError):
                prompt("Name")

    def test_non_string_message_raises_type_error(self):
        with self.assertRaises(TypeError):
            prompt(123)

    def test_non_string_default_raises_type_error(self):
        with self.assertRaises(TypeError):
            prompt("Name", default=5)


if __name__ == "__main__":
    unittest.main()
TESTTERMINALUTILS

# --- tests/test_subprocess_utils.py ---
cat > "$OUTPUT_DIR/tests/test_subprocess_utils.py" <<'TESTSUBPROCESSUTILS'
"""Tests for subprocess_utils module."""

from __future__ import annotations

import subprocess
import unittest

from subprocess_utils import check_call, check_output, run_command


class TestRunCommand(unittest.TestCase):
    def test_run_command_echo(self) -> None:
        result = run_command(["echo", "hello"], capture_output=True)
        self.assertEqual(result.returncode, 0)

    def test_run_command_check_true_success(self) -> None:
        result = run_command(["true"], check=True)
        self.assertEqual(result.returncode, 0)

    def test_run_command_check_true_failure(self) -> None:
        with self.assertRaises(subprocess.CalledProcessError):
            run_command(["false"], check=True)

    def test_run_command_invalid_type(self) -> None:
        with self.assertRaises(TypeError):
            run_command(123)  # type: ignore[arg-type]


class TestCheckOutput(unittest.TestCase):
    def test_check_output_echo(self) -> None:
        output = check_output(["echo", "test"], text=True)
        if isinstance(output, str):
            self.assertEqual(output.strip(), "test")

    def test_check_output_failure(self) -> None:
        with self.assertRaises(subprocess.CalledProcessError):
            check_output(["false"])

    def test_check_output_invalid_type(self) -> None:
        with self.assertRaises(TypeError):
            check_output(123)  # type: ignore[arg-type]


class TestCheckCall(unittest.TestCase):
    def test_check_call_success(self) -> None:
        returncode = check_call(["true"])
        self.assertEqual(returncode, 0)

    def test_check_call_failure(self) -> None:
        with self.assertRaises(subprocess.CalledProcessError):
            check_call(["false"])

    def test_check_call_invalid_type(self) -> None:
        with self.assertRaises(TypeError):
            check_call(123)  # type: ignore[arg-type]


if __name__ == "__main__":
    unittest.main()
TESTSUBPROCESSUTILS
