"""Tests for codecs_utils."""

import codecs

from codecs_utils import (
    decode,
    encode,
    getdecoder,
    getencoder,
    getincrementaldecoder,
    getincrementalencoder,
    getreader,
    getwriter,
    lookup,
    lookup_error,
    register,
    register_error,
)
from codecs_utils import (
    open as codecs_open,
)


def test_encode_decode():
    assert decode(encode("hello", "utf-8"), "utf-8") == "hello"


