    def test_non_string_target_raises(self):
        dt = datetime.datetime(2024, 1, 15, 12, 0, 0)
        with self.assertRaises(TypeError):
            convert_datetime(dt, 123)  # type: ignore[arg-type]


class TestFormatDatetime(unittest.TestCase):
