cat > "$OUTPUT_DIR/tests/test_cmath_utils.py" <<'TESTCMATHUTILS'
import math
import unittest

from cmath_utils import (
    acos,
    acosh,
    asin,
    asinh,
    atan,
    atanh,
    cos,
    cosh,
    exp,
    isclose,
    isfinite,
    isinf,
    isnan,
    log,
    log10,
    phase,
    polar,
    rect,
    sin,
    sinh,
    sqrt,
    tan,
    tanh,
)


class TestPhase(unittest.TestCase):
    def test_phase_positive_real(self):
        self.assertEqual(phase(1), 0.0)

    def test_phase_negative_real(self):
        self.assertEqual(phase(-1), math.pi)

    def test_phase_complex(self):
        self.assertAlmostEqual(phase(1 + 1j), math.pi / 4)

    def test_phase_invalid(self):
        with self.assertRaises(TypeError):
            phase("1+1j")  # type: ignore[arg-type]


class TestPolar(unittest.TestCase):
    def test_polar_one(self):
        self.assertEqual(polar(1), (1.0, 0.0))

    def test_polar_complex(self):
        modulus, ph = polar(1 + 1j)
        self.assertAlmostEqual(modulus, math.sqrt(2))
        self.assertAlmostEqual(ph, math.pi / 4)

    def test_polar_invalid(self):
        with self.assertRaises(TypeError):
            polar([1, 2])  # type: ignore[arg-type]


class TestRect(unittest.TestCase):
    def test_rect_roundtrip(self):
        r, phi = 2.0, math.pi / 3
        z = rect(r, phi)
        modulus, phase = polar(z)
        self.assertAlmostEqual(modulus, r)
        self.assertAlmostEqual(phase % (2 * math.pi), phi % (2 * math.pi))

    def test_rect_zero(self):
        self.assertEqual(rect(0, 5), 0j)

    def test_rect_invalid_r(self):
        with self.assertRaises(TypeError):
            rect("2", 1)  # type: ignore[arg-type]

    def test_rect_invalid_phi(self):
        with self.assertRaises(TypeError):
            rect(2, "1")  # type: ignore[arg-type]


class TestExp(unittest.TestCase):
    def test_exp_zero(self):
        self.assertEqual(exp(0), 1 + 0j)

    def test_exp_one(self):
        self.assertAlmostEqual(exp(1).real, math.e)
        self.assertAlmostEqual(exp(1).imag, 0.0)

    def test_exp_invalid(self):
        with self.assertRaises(TypeError):
            exp(None)  # type: ignore[arg-type]


class TestLog(unittest.TestCase):
    def test_log_one(self):
        self.assertEqual(log(1), 0j)

    def test_log_e(self):
        self.assertAlmostEqual(log(math.e).real, 1.0)
        self.assertAlmostEqual(log(math.e).imag, 0.0)

    def test_log_base(self):
        self.assertAlmostEqual(log(8, 2).real, 3.0)
        self.assertAlmostEqual(log(8, 2).imag, 0.0)

    def test_log_invalid(self):
        with self.assertRaises(TypeError):
            log("1")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            log(1, "2")  # type: ignore[arg-type]


class TestLog10(unittest.TestCase):
    def test_log10_one(self):
        self.assertEqual(log10(1), 0j)

    def test_log10_hundred(self):
        self.assertAlmostEqual(log10(100).real, 2.0)
        self.assertAlmostEqual(log10(100).imag, 0.0)

    def test_log10_invalid(self):
        with self.assertRaises(TypeError):
            log10([100])  # type: ignore[arg-type]


class TestSqrt(unittest.TestCase):
    def test_sqrt_negative(self):
        self.assertEqual(sqrt(-1), 1j)

    def test_sqrt_positive(self):
        self.assertEqual(sqrt(4), 2 + 0j)

    def test_sqrt_invalid(self):
        with self.assertRaises(TypeError):
            sqrt("4")  # type: ignore[arg-type]


class TestTrig(unittest.TestCase):
    def test_sin_cos(self):
        self.assertEqual(sin(0), 0j)
        self.assertAlmostEqual(sin(math.pi / 2).real, 1.0)
        self.assertAlmostEqual(cos(0).real, 1.0)
        self.assertAlmostEqual(cos(math.pi).real, -1.0)

    def test_tan(self):
        self.assertEqual(tan(0), 0j)

    def test_invalid(self):
        with self.assertRaises(TypeError):
            sin("x")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            cos("x")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            tan("x")  # type: ignore[arg-type]


class TestInverseTrig(unittest.TestCase):
    def test_asin_acos_atan(self):
        self.assertEqual(asin(0), 0j)
        self.assertAlmostEqual(asin(1).real, math.pi / 2)
        self.assertEqual(acos(1), 0j)
        self.assertAlmostEqual(acos(0).real, math.pi / 2)
        self.assertEqual(atan(0), 0j)
        self.assertAlmostEqual(atan(1).real, math.pi / 4)

    def test_invalid(self):
        with self.assertRaises(TypeError):
            asin("x")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            acos("x")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            atan("x")  # type: ignore[arg-type]


class TestHyperbolic(unittest.TestCase):
    def test_sinh_cosh_tanh(self):
        self.assertEqual(sinh(0), 0j)
        self.assertEqual(cosh(0), 1 + 0j)
        self.assertEqual(tanh(0), 0j)

    def test_inverse(self):
        self.assertEqual(asinh(0), 0j)
        self.assertEqual(acosh(1), 0j)
        self.assertEqual(atanh(0), 0j)

    def test_invalid(self):
        with self.assertRaises(TypeError):
            sinh("x")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            cosh("x")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            tanh("x")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            asinh("x")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            acosh("x")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            atanh("x")  # type: ignore[arg-type]


class TestClassification(unittest.TestCase):
    def test_isfinite(self):
        self.assertTrue(isfinite(1 + 2j))
        self.assertFalse(isfinite(complex(math.inf, 0)))
        self.assertFalse(isfinite(complex(0, math.inf)))
        self.assertFalse(isfinite(complex(math.nan, 0)))

    def test_isinf(self):
        self.assertTrue(isinf(complex(math.inf, 0)))
        self.assertFalse(isinf(1 + 2j))

    def test_isnan(self):
        self.assertTrue(isnan(complex(math.nan, 0)))
        self.assertFalse(isnan(1 + 2j))

    def test_invalid(self):
        with self.assertRaises(TypeError):
            isfinite("x")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            isinf("x")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            isnan("x")  # type: ignore[arg-type]


class TestIsClose(unittest.TestCase):
    def test_isclose_same(self):
        self.assertTrue(isclose(1 + 1j, 1 + 1j))

    def test_isclose_different(self):
        self.assertFalse(isclose(1 + 1j, 1 + 2j))

    def test_isclose_tolerance(self):
        self.assertTrue(isclose(1 + 1j, 1 + 1.0000000001j))
        self.assertFalse(isclose(1 + 1j, 1 + 2j, abs_tol=0.5))

    def test_invalid(self):
        with self.assertRaises(TypeError):
            isclose("x", 1)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            isclose(1, "x")  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            isclose(1, 1, rel_tol=-1)
        with self.assertRaises(ValueError):
            isclose(1, 1, abs_tol=-1)


if __name__ == "__main__":
    unittest.main()
TESTCMATHUTILS

# --- threading_utils.py ---
cat > "$OUTPUT_DIR/threading_utils.py" <<'THREADINGUTILS'
"""Threading utilities wrapping the standard library threading module.

This module provides a validated wrapper around the standard library ``threading``
module for lock, semaphore, event, condition, timer, and thread operations. All
functions validate their inputs and raise ``TypeError`` for invalid arguments.
"""

from __future__ import annotations

import threading
from typing import Any, Callable, Optional, TypeVar

T = TypeVar("T")

# threading.Lock is a factory function, not a class, so capture the actual lock type.
_LockType = type(threading.Lock())


def _validate_callable(value: Any, name: str) -> None:
    """Validate that *value* is callable, raising ``TypeError`` otherwise.

    Args:
        value: The value to validate.
        name: The name of the argument (used in error messages).

    Raises:
        TypeError: If value is not callable.
    """
    if not callable(value):
        raise TypeError(f"{name} must be callable")


def _validate_positive_int(value: Any, name: str) -> None:
    """Validate that *value* is a positive integer, raising ``TypeError`` otherwise.

    Args:
        value: The value to validate.
        name: The name of the argument (used in error messages).

    Raises:
        TypeError: If value is not a positive integer.
    """
    if isinstance(value, bool) or not isinstance(value, int) or value < 1:
        raise TypeError(f"{name} must be a positive integer")


def _validate_non_negative_int(value: Any, name: str) -> None:
    """Validate that *value* is a non-negative integer, raising ``TypeError`` otherwise.

    Args:
        value: The value to validate.
        name: The name of the argument (used in error messages).

    Raises:
        TypeError: If value is not a non-negative integer.
    """
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise TypeError(f"{name} must be a non-negative integer")


def _validate_non_negative_float(value: Any, name: str) -> None:
    """Validate that *value* is a non-negative real number, raising ``TypeError`` otherwise.

    Args:
        value: The value to validate.
        name: The name of the argument (used in error messages).

    Raises:
        TypeError: If value is not a non-negative int or float.
    """
    if isinstance(value, bool) or not isinstance(value, (int, float)) or value < 0:
        raise TypeError(f"{name} must be a non-negative number")


def create_lock() -> threading.Lock:
    """Return a new :class:`threading.Lock`.

    Returns:
        An unlocked lock object.
    """
    return threading.Lock()


def create_rlock() -> threading.RLock:
    """Return a new :class:`threading.RLock` (reentrant lock).

    Returns:
        An unlocked reentrant lock object.
    """
    return threading.RLock()


def create_semaphore(value: int = 1) -> threading.Semaphore:
    """Return a new :class:`threading.Semaphore` with the given initial value.

    Args:
        value: The initial internal counter (default: 1).

    Returns:
        A semaphore object.

    Raises:
        TypeError: If value is not a non-negative integer.

    Examples:
        >>> sem = create_semaphore(2)
        >>> sem.acquire()
        True
        >>> sem.acquire()
        True
        >>> sem.acquire(blocking=False)
        False
    """
    _validate_non_negative_int(value, "value")
    return threading.Semaphore(value)


def create_bounded_semaphore(value: int = 1) -> threading.BoundedSemaphore:
    """Return a new :class:`threading.BoundedSemaphore` with the given initial value.

    Args:
        value: The initial internal counter (default: 1).

    Returns:
        A bounded semaphore object.

    Raises:
        TypeError: If value is not a non-negative integer.
    """
    _validate_non_negative_int(value, "value")
    return threading.BoundedSemaphore(value)


def create_event() -> threading.Event:
    """Return a new :class:`threading.Event` with its internal flag set to false.

    Returns:
        An event object.
    """
    return threading.Event()


def create_condition(lock: Optional[threading.Lock] = None) -> threading.Condition:
    """Return a new :class:`threading.Condition` using the given lock.

    Args:
        lock: An optional lock to use. If omitted, a new lock is created.

    Returns:
        A condition variable object.

    Raises:
        TypeError: If lock is not a :class:`threading.Lock` or ``None``.
    """
    if lock is not None and not isinstance(lock, _LockType):
        raise TypeError("lock must be a threading.Lock or None")
    return threading.Condition(lock=lock)


def create_timer(
    interval: float,
    function: Callable[..., None],
    args: Optional[tuple] = None,
    kwargs: Optional[dict] = None,
) -> threading.Timer:
    """Return a new :class:`threading.Timer` that runs *function* after *interval* seconds.

    Args:
        interval: The number of seconds to wait before calling *function*.
        function: The callable to invoke after the interval.
        args: Optional positional arguments to pass to *function*.
        kwargs: Optional keyword arguments to pass to *function*.

    Returns:
        A timer object (not yet started).

    Raises:
        TypeError: If interval is not a non-negative number or function is not callable.

    Examples:
        >>> timer = create_timer(0.01, lambda: None)
        >>> timer.cancel()
    """
    _validate_non_negative_float(interval, "interval")
    _validate_callable(function, "function")
    return threading.Timer(interval, function, args=args or (), kwargs=kwargs or {})


def create_thread(
    target: Callable[..., T],
    args: Optional[tuple] = None,
    kwargs: Optional[dict] = None,
    name: Optional[str] = None,
    daemon: bool = False,
) -> threading.Thread:
    """Return a new :class:`threading.Thread` configured with the given settings.

    Args:
        target: The callable to invoke in the new thread.
        args: Optional positional arguments to pass to *target*.
        kwargs: Optional keyword arguments to pass to *target*.
        name: Optional thread name.
        daemon: Whether the thread is a daemon thread (default: False).

    Returns:
        A thread object (not yet started).

    Raises:
        TypeError: If target is not callable, name is not a string or None, or daemon is not a bool.
    """
    _validate_callable(target, "target")
    if name is not None and not isinstance(name, str):
        raise TypeError("name must be a string or None")
    if not isinstance(daemon, bool):
        raise TypeError("daemon must be a bool")
    return threading.Thread(
        target=target, args=args or (), kwargs=kwargs or {}, name=name, daemon=daemon
    )


def current_thread() -> threading.Thread:
    """Return the :class:`threading.Thread` object corresponding to the caller's thread.

    Returns:
        The current thread object.
    """
    return threading.current_thread()


def active_count() -> int:
    """Return the number of :class:`threading.Thread` objects currently alive.

    Returns:
        The count of alive threads (including the caller).
    """
    return threading.active_count()


def enumerate_threads() -> list[threading.Thread]:
    """Return a list of all :class:`threading.Thread` objects currently alive.

    Returns:
        A list of alive thread objects.
    """
    return list(threading.enumerate())


def synchronized(
    lock: Optional[threading.Lock] = None,
) -> Callable[[Callable[..., T]], Callable[..., T]]:
    """Return a decorator that serializes calls to a function using a lock.

    Args:
        lock: An optional lock to use. If omitted, a new lock is created per decorated function.

    Returns:
        A decorator that wraps *func* so concurrent calls are serialized.

    Raises:
        TypeError: If lock is not a :class:`threading.Lock` or ``None``.
    """
    if lock is None:
        lock = threading.Lock()
    elif not isinstance(lock, _LockType):
        raise TypeError("lock must be a threading.Lock or None")

    def decorator(func: Callable[..., T]) -> Callable[..., T]:
        def wrapper(*args: Any, **kwargs: Any) -> T:
            with lock:
                return func(*args, **kwargs)

        return wrapper

    return decorator
THREADINGUTILS

# --- tests/test_threading_utils.py ---
cat > "$OUTPUT_DIR/tests/test_threading_utils.py" <<'TESTTHREADINGUTILS'
import threading
import unittest

from threading_utils import (
    active_count,
    create_bounded_semaphore,
    create_condition,
    create_event,
    create_lock,
    create_rlock,
    create_semaphore,
    create_thread,
    create_timer,
    current_thread,
    enumerate_threads,
    synchronized,
)


class TestLocks(unittest.TestCase):
    def test_create_lock(self):
        lock = create_lock()
        self.assertIsInstance(lock, type(threading.Lock()))

    def test_create_rlock(self):
        lock = create_rlock()
        self.assertIsInstance(lock, type(threading.RLock()))


class TestSemaphores(unittest.TestCase):
    def test_create_semaphore_default(self):
        sem = create_semaphore()
        self.assertIsInstance(sem, threading.Semaphore)

    def test_create_semaphore_value(self):
        sem = create_semaphore(3)
        self.assertTrue(sem.acquire())
        self.assertTrue(sem.acquire())
        self.assertFalse(sem.acquire(blocking=False))

    def test_create_bounded_semaphore(self):
        sem = create_bounded_semaphore(1)
        self.assertIsInstance(sem, threading.BoundedSemaphore)

    def test_create_semaphore_invalid(self):
        with self.assertRaises(TypeError):
            create_semaphore(-1)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            create_semaphore("1")  # type: ignore[arg-type]


class TestEvent(unittest.TestCase):
    def test_create_event(self):
        event = create_event()
        self.assertIsInstance(event, threading.Event)
        self.assertFalse(event.is_set())
        event.set()
        self.assertTrue(event.is_set())
        event.clear()
        self.assertFalse(event.is_set())


class TestCondition(unittest.TestCase):
    def test_create_condition_default(self):
        cond = create_condition()
        self.assertIsInstance(cond, threading.Condition)

    def test_create_condition_with_lock(self):
        lock = create_lock()
        cond = create_condition(lock)
        self.assertIsInstance(cond, threading.Condition)

    def test_create_condition_invalid_lock(self):
        with self.assertRaises(TypeError):
            create_condition("not a lock")  # type: ignore[arg-type]


class TestTimer(unittest.TestCase):
    def test_create_timer(self):
        called = []

        def callback() -> None:
            called.append(True)

        timer = create_timer(0.01, callback)
        self.assertIsInstance(timer, threading.Timer)
        timer.cancel()

    def test_create_timer_invalid(self):
        with self.assertRaises(TypeError):
            create_timer(-1, lambda: None)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            create_timer(0.01, "not callable")  # type: ignore[arg-type]


class TestThread(unittest.TestCase):
    def test_create_thread(self):
        results = []

        def worker() -> None:
            results.append(1)

        thread = create_thread(worker)
        self.assertIsInstance(thread, threading.Thread)
        thread.start()
        thread.join()
        self.assertEqual(results, [1])

    def test_create_thread_with_args(self):
        results = []

        def worker(a, b=0) -> None:
            results.append(a + b)

        thread = create_thread(worker, args=(2,), kwargs={"b": 3})
        thread.start()
        thread.join()
        self.assertEqual(results, [5])

    def test_create_thread_daemon(self):
        thread = create_thread(lambda: None, daemon=True)
        self.assertTrue(thread.daemon)

    def test_create_thread_invalid(self):
        with self.assertRaises(TypeError):
            create_thread("not callable")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            create_thread(lambda: None, name=123)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            create_thread(lambda: None, daemon="yes")  # type: ignore[arg-type]


class TestIntrospection(unittest.TestCase):
    def test_current_thread(self):
        thread = current_thread()
        self.assertIsInstance(thread, threading.Thread)

    def test_active_count(self):
        self.assertGreaterEqual(active_count(), 1)

    def test_enumerate_threads(self):
        threads = enumerate_threads()
        self.assertIsInstance(threads, list)
        self.assertGreaterEqual(len(threads), 1)
        self.assertIn(current_thread(), threads)


class TestSynchronized(unittest.TestCase):
    def test_synchronized_serializes(self):
        lock = create_lock()
        results = []

        @synchronized(lock)
        def worker(value: int) -> int:
            results.append(value)
            return value

        threads = [threading.Thread(target=lambda v=i: worker(v)) for i in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        self.assertEqual(sorted(results), list(range(10)))

    def test_synchronized_default_lock(self):
        @synchronized()
        def worker(value: int) -> int:
            return value

        self.assertEqual(worker(42), 42)

    def test_synchronized_invalid_lock(self):
        with self.assertRaises(TypeError):
            synchronized("not a lock")  # type: ignore[arg-type]


if __name__ == "__main__":
    unittest.main()
TESTTHREADINGUTILS

# --- selectors_utils.py ---
cat > "$OUTPUT_DIR/selectors_utils.py" <<'SELECTORS_UTILS'
"""Selectors utilities wrapping the standard library selectors module.

This module provides a validated wrapper around the standard library ``selecters``
module for I/O multiplexing: creating default selectors, registering and
unregistering file objects, selecting ready I/O, and inspecting selector state.
All functions validate their inputs and raise ``TypeError`` for invalid arguments.
"""

from __future__ import annotations

import selectors
from typing import Any, Optional

# Re-export the standard event masks for convenience.
EVENT_READ = selectors.EVENT_READ
EVENT_WRITE = selectors.EVENT_WRITE

# Bitmask of every event flag the standard library selectors module defines.
_ALL_EVENTS = selectors.EVENT_READ | selectors.EVENT_WRITE


def _validate_fileobj(value: Any, name: str) -> None:
    """Validate that *value* is a file object or integer file descriptor.

    Args:
        value: The value to validate.
        name: The name of the argument (used in error messages).

    Raises:
        TypeError: If value is neither an int nor an object with ``fileno``.
    """
    if isinstance(value, int):
        return
    if not hasattr(value, "fileno"):
        raise TypeError(f"{name} must be a file object or integer file descriptor")


def _validate_events(events: Any, name: str) -> None:
    """Validate that *events* is a non-negative combination of selector event flags.

    Args:
        events: The event mask to validate.
        name: The name of the argument (used in error messages).

    Raises:
        TypeError: If events is not an integer.
        ValueError: If events contains flags other than EVENT_READ/EVENT_WRITE.
    """
    if isinstance(events, bool) or not isinstance(events, int):
        raise TypeError(f"{name} must be an integer")
    if events < 0:
        raise ValueError(f"{name} must be non-negative")
    if events & ~_ALL_EVENTS:
        raise ValueError(f"{name} must only contain EVENT_READ and EVENT_WRITE")


def _validate_timeout(timeout: Any, name: str) -> None:
    """Validate that *timeout* is None or a non-negative real number.

    Args:
        timeout: The timeout value to validate.
        name: The name of the argument (used in error messages).

    Raises:
        TypeError: If timeout is not None or a real number.
        ValueError: If timeout is negative.
    """
    if timeout is None:
        return
    if isinstance(timeout, bool) or not isinstance(timeout, (int, float)):
        raise TypeError(f"{name} must be a number or None")
    if timeout < 0:
        raise ValueError(f"{name} must be non-negative")


def create_default_selector() -> selectors.DefaultSelector:
    """Return a new :class:`selectors.DefaultSelector` for the current platform.

    Returns:
        A default selector object ready for registrations.
    """
    return selectors.DefaultSelector()


def register(
    selector: selectors.BaseSelector,
    fileobj: Any,
    events: int,
    data: Optional[Any] = None,
) -> selectors.SelectorKey:
    """Register a file object with *selector* to be monitored for *events*.

    Args:
        selector: The selector to register with.
        fileobj: The file object (or integer file descriptor) to monitor.
        events: Event mask combining :data:`EVENT_READ` and/or :data:`EVENT_WRITE`.
        data: Optional opaque data to associate with the registration.

    Returns:
        A :class:`selectors.SelectorKey` describing the registration.

    Raises:
        TypeError: If selector is not a :class:`selectors.BaseSelector`, fileobj is
            invalid, or events is not an integer.
        ValueError: If events contains flags other than EVENT_READ/EVENT_WRITE.
    """
    if not isinstance(selector, selectors.BaseSelector):
        raise TypeError("selector must be a selectors.BaseSelector")
    _validate_fileobj(fileobj, "fileobj")
    _validate_events(events, "events")
    return selector.register(fileobj, events, data=data)


def unregister(
    selector: selectors.BaseSelector, fileobj: Any
) -> selectors.SelectorKey:
    """Unregister a file object from *selector*.

    Args:
        selector: The selector to unregister from.
        fileobj: The file object (or integer file descriptor) to stop monitoring.

    Returns:
        The :class:`selectors.SelectorKey` that was removed.

    Raises:
        TypeError: If selector is not a :class:`selectors.BaseSelector` or fileobj
            is invalid.
        KeyError: If fileobj is not currently registered.
    """
    if not isinstance(selector, selectors.BaseSelector):
        raise TypeError("selector must be a selectors.BaseSelector")
    _validate_fileobj(fileobj, "fileobj")
    return selector.unregister(fileobj)


def select(
    selector: selectors.BaseSelector, timeout: Optional[float] = None
) -> list[tuple[selectors.SelectorKey, int]]:
    """Wait until some registered file objects are ready for I/O.

    Args:
        selector: The selector to wait on.
        timeout: Maximum time to wait in seconds (None blocks indefinitely).

    Returns:
        A list of ``(key, events)`` tuples for the file objects that are ready.

    Raises:
        TypeError: If selector is not a :class:`selectors.BaseSelector` or timeout
            is not a number or None.
        ValueError: If timeout is negative.
    """
    if not isinstance(selector, selectors.BaseSelector):
        raise TypeError("selector must be a selectors.BaseSelector")
    _validate_timeout(timeout, "timeout")
    return selector.select(timeout)


def get_key(selector: selectors.BaseSelector, fileobj: Any) -> selectors.SelectorKey:
    """Return the :class:`selectors.SelectorKey` for a registered file object.

    Args:
        selector: The selector to query.
        fileobj: The file object (or integer file descriptor) to look up.

    Returns:
        The selector key associated with *fileobj*.

    Raises:
        TypeError: If selector is not a :class:`selectors.BaseSelector` or fileobj
            is invalid.
        KeyError: If fileobj is not currently registered.
    """
    if not isinstance(selector, selectors.BaseSelector):
        raise TypeError("selector must be a selectors.BaseSelector")
    _validate_fileobj(fileobj, "fileobj")
    return selector.get_key(fileobj)


def get_map(selector: selectors.BaseSelector) -> dict[Any, selectors.SelectorKey]:
    """Return the mapping of registered file objects to their selector keys.

    Args:
        selector: The selector to query.

    Returns:
        A dictionary mapping file objects to :class:`selectors.SelectorKey` values.

    Raises:
        TypeError: If selector is not a :class:`selectors.BaseSelector`.
    """
    if not isinstance(selector, selectors.BaseSelector):
        raise TypeError("selector must be a selectors.BaseSelector")
    return dict(selector.get_map())


def close_selector(selector: selectors.BaseSelector) -> None:
    """Close *selector* and release any underlying resources.

    After calling this, the selector must not be used again.

    Args:
        selector: The selector to close.

    Raises:
        TypeError: If selector is not a :class:`selectors.BaseSelector`.
    """
    if not isinstance(selector, selectors.BaseSelector):
        raise TypeError("selector must be a selectors.BaseSelector")
    selector.close()
SELECTORS_UTILS

