        finally:
            selector.close()


class TestGetMap(unittest.TestCase):
    def test_get_map(self):
        selector = create_default_selector()
        try:
            reader, _ = socket.socketpair()
            register(selector, reader, EVENT_READ)
            mapping = get_map(selector)
