"""Utilities for SQLite database access (wrapping :mod:`sqlite3`).

This module provides a small, validated layer over the standard library
``sqlite3`` module for opening connections, executing statements, fetching
rows, and inspecting schema. All functions validate their inputs and raise
``TypeError`` or ``ValueError`` on invalid arguments.
"""

import sqlite3 as _sqlite3
from typing import Any, Optional, Sequence


def connect(database: str = ":memory:", *, timeout: float = 5.0) -> _sqlite3.Connection:
    """Open a connection to the SQLite database *database*.

    Args:
        database: Path to the database file, or ``":memory:"`` for an
            in-memory database.
        timeout: How long to wait for a lock before raising, in seconds.

    Returns:
        A :class:`sqlite3.Connection`.

    Raises:
        TypeError: If *database* is not a str or *timeout* is not a real
            number.
        ValueError: If *timeout* is negative.
    """
    if not isinstance(database, str):
        raise TypeError("database must be a str")
    if not isinstance(timeout, (int, float)) or isinstance(timeout, bool):
        raise TypeError("timeout must be a real number")
    if timeout < 0:
        raise ValueError("timeout must be non-negative")
    return _sqlite3.connect(database, timeout=float(timeout))


def execute(
    conn: _sqlite3.Connection, sql: str, params: Sequence[Any] = ()
) -> _sqlite3.Cursor:
    """Execute *sql* with optional *params* on *conn* and return the cursor.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        sql: The SQL statement to execute.
        params: Optional sequence of query parameters.

    Returns:
        The :class:`sqlite3.Cursor` after execution.

    Raises:
        TypeError: If *conn* is not a Connection, *sql* is not a str, or
            *params* is not a sequence.
    """
    if not isinstance(conn, _sqlite3.Connection):
        raise TypeError("conn must be a sqlite3.Connection")
    if not isinstance(sql, str):
        raise TypeError("sql must be a str")
    if not isinstance(params, (list, tuple)):
        raise TypeError("params must be a list or tuple")
    return conn.execute(sql, tuple(params))


def executemany(
    conn: _sqlite3.Connection, sql: str, params_list: Sequence[Sequence[Any]]
) -> _sqlite3.Cursor:
    """Execute *sql* against every parameter sequence in *params_list*.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        sql: The SQL statement to execute.
        params_list: A sequence of parameter sequences, one per execution.

    Returns:
        The :class:`sqlite3.Cursor` after execution.

    Raises:
        TypeError: If *conn* is not a Connection, *sql* is not a str, or
            *params_list* is not a sequence of sequences.
    """
    if not isinstance(conn, _sqlite3.Connection):
        raise TypeError("conn must be a sqlite3.Connection")
    if not isinstance(sql, str):
        raise TypeError("sql must be a str")
    if not isinstance(params_list, (list, tuple)):
        raise TypeError("params_list must be a list or tuple")
    for params in params_list:
        if not isinstance(params, (list, tuple)):
            raise TypeError("each entry in params_list must be a list or tuple")
    return conn.executemany(sql, [tuple(params) for params in params_list])


def fetch_all(
    conn: _sqlite3.Connection, sql: str, params: Sequence[Any] = ()
) -> list[tuple[Any, ...]]:
    """Execute *sql* and return all matching rows.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        sql: The SQL SELECT statement to execute.
        params: Optional sequence of query parameters.

    Returns:
        A list of rows, each row as a tuple of column values.
    """
    cursor = execute(conn, sql, params)
    return list(cursor.fetchall())


def fetch_one(
    conn: _sqlite3.Connection, sql: str, params: Sequence[Any] = ()
) -> Optional[tuple[Any, ...]]:
    """Execute *sql* and return the first matching row, or ``None``.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        sql: The SQL SELECT statement to execute.
        params: Optional sequence of query parameters.

    Returns:
        The first row as a tuple, or ``None`` when no rows match.
    """
    cursor = execute(conn, sql, params)
    return cursor.fetchone()


def fetch_many(
    conn: _sqlite3.Connection,
    sql: str,
    size: int,
    params: Sequence[Any] = (),
) -> list[tuple[Any, ...]]:
    """Execute *sql* and return up to *size* matching rows.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        sql: The SQL SELECT statement to execute.
        size: Maximum number of rows to return.
        params: Optional sequence of query parameters.

    Returns:
        A list of up to *size* rows.

    Raises:
        TypeError: If *size* is not an int.
        ValueError: If *size* is negative.
    """
    if not isinstance(size, int) or isinstance(size, bool):
        raise TypeError("size must be an int")
    if size < 0:
        raise ValueError("size must be non-negative")
    cursor = execute(conn, sql, params)
    return list(cursor.fetchmany(size))


def create_table(conn: _sqlite3.Connection, table: str, columns: str) -> None:
    """Create *table* with the given *columns* SQL fragment if it does not exist.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        table: Name of the table to create.
        columns: SQL column definitions (e.g. ``"id INTEGER PRIMARY KEY, name TEXT"``).

    Raises:
        TypeError: If *conn* is not a Connection or *table*/*columns* are not strs.
        ValueError: If *table* or *columns* is empty.
    """
    if not isinstance(conn, _sqlite3.Connection):
        raise TypeError("conn must be a sqlite3.Connection")
    if not isinstance(table, str):
        raise TypeError("table must be a str")
    if not isinstance(columns, str):
        raise TypeError("columns must be a str")
    if not table:
        raise ValueError("table must not be empty")
    if not columns.strip():
        raise ValueError("columns must not be empty")
    conn.execute(f"CREATE TABLE IF NOT EXISTS {table} ({columns})")
    conn.commit()


def insert_row(
    conn: _sqlite3.Connection,
    table: str,
    columns: Sequence[str],
    values: Sequence[Any],
) -> int:
    """Insert a row into *table* and return the new row id.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        table: Name of the table to insert into.
        columns: Sequence of column names.
        values: Sequence of column values, aligned with *columns*.

    Returns:
        The row id of the inserted row.

    Raises:
        TypeError: If *conn* is not a Connection or *table* is not a str, or
            *columns*/*values* are not sequences of the right kind.
        ValueError: If *table* is empty or *columns* and *values* differ in length.
    """
    if not isinstance(conn, _sqlite3.Connection):
        raise TypeError("conn must be a sqlite3.Connection")
    if not isinstance(table, str):
        raise TypeError("table must be a str")
    if not table:
        raise ValueError("table must not be empty")
    if not isinstance(columns, (list, tuple)) or not all(
        isinstance(c, str) for c in columns
    ):
        raise TypeError("columns must be a list or tuple of strs")
    if not isinstance(values, (list, tuple)):
        raise TypeError("values must be a list or tuple")
    if len(columns) != len(values):
        raise ValueError("columns and values must have the same length")
    placeholders = ", ".join("?" for _ in columns)
    col_list = ", ".join(columns)
    cursor = conn.execute(
        f"INSERT INTO {table} ({col_list}) VALUES ({placeholders})",
        tuple(values),
    )
    conn.commit()
    return int(cursor.lastrowid)


def query(
    conn: _sqlite3.Connection, sql: str, params: Sequence[Any] = ()
) -> list[dict[str, Any]]:
    """Execute *sql* and return rows as dictionaries keyed by column name.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        sql: The SQL SELECT statement to execute.
        params: Optional sequence of query parameters.

    Returns:
        A list of row dictionaries.
    """
    cursor = execute(conn, sql, params)
    description = cursor.description
    if description is None:
        return []
    column_names = [desc[0] for desc in description]
    return [dict(zip(column_names, row)) for row in cursor.fetchall()]


def table_exists(conn: _sqlite3.Connection, table: str) -> bool:
    """Return ``True`` if *table* exists in the database.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        table: Name of the table to check.

    Returns:
        ``True`` when a table named *table* exists, otherwise ``False``.

    Raises:
        TypeError: If *conn* is not a Connection or *table* is not a str.
        ValueError: If *table* is empty.
    """
    if not isinstance(conn, _sqlite3.Connection):
        raise TypeError("conn must be a sqlite3.Connection")
    if not isinstance(table, str):
        raise TypeError("table must be a str")
    if not table:
        raise ValueError("table must not be empty")
    cursor = conn.execute(
        "SELECT name FROM sqlite_master WHERE type='table' AND name=?", (table,)
    )
    return cursor.fetchone() is not None
SQLITE3_UTILS

# --- tests/test_sqlite3_utils.py ---
cat > "$OUTPUT_DIR/tests/test_sqlite3_utils.py" <<'TEST_SQLITE3_UTILS'
"""Tests for sqlite3_utils."""

import sqlite3
import unittest

from sqlite3_utils import (
    connect,
    create_table,
    executemany,
    execute,
    fetch_all,
    fetch_many,
    fetch_one,
    insert_row,
    query,
    table_exists,
)


class TestSqlite3Utils(unittest.TestCase):
    def setUp(self) -> None:
        self.conn = connect(":memory:")
        create_table(
            self.conn,
            "users",
            "id INTEGER PRIMARY KEY, name TEXT NOT NULL, score REAL",
        )

    def tearDown(self) -> None:
        self.conn.close()

    def test_connect_returns_connection(self):
        self.assertIsInstance(self.conn, sqlite3.Connection)

    def test_connect_in_memory_default(self):
        conn = connect()
        try:
            self.assertIsInstance(conn, sqlite3.Connection)
        finally:
            conn.close()

    def test_connect_type_errors(self):
        with self.assertRaises(TypeError):
            connect(123)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            connect(":memory:", timeout="slow")  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            connect(":memory:", timeout=-1)

    def test_insert_row_and_fetch_one(self):
        row_id = insert_row(self.conn, "users", ["name", "score"], ["Ada", 92.5])
        self.assertEqual(row_id, 1)
        row = fetch_one(self.conn, "SELECT name, score FROM users WHERE id = ?", [1])
        self.assertEqual(row, ("Ada", 92.5))

    def test_insert_row_validation(self):
        with self.assertRaises(TypeError):
            insert_row(self.conn, 1, ["name"], ["x"])  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            insert_row(self.conn, "", ["name"], ["x"])
        with self.assertRaises(ValueError):
            insert_row(self.conn, "users", ["name", "score"], ["x"])
        with self.assertRaises(TypeError):
            insert_row(self.conn, "users", ["name"], "x")  # type: ignore[arg-type]

    def test_fetch_all(self):
        insert_row(self.conn, "users", ["name", "score"], ["Ada", 92.5])
        insert_row(self.conn, "users", ["name", "score"], ["Bob", 87.0])
        rows = fetch_all(self.conn, "SELECT name FROM users ORDER BY name")
        self.assertEqual(rows, [("Ada",), ("Bob",)])

    def test_fetch_many(self):
        insert_row(self.conn, "users", ["name", "score"], ["Ada", 92.5])
        insert_row(self.conn, "users", ["name", "score"], ["Bob", 87.0])
        insert_row(self.conn, "users", ["name", "score"], ["Cec", 91.0])
        rows = fetch_many(self.conn, "SELECT name FROM users ORDER BY name", 2)
        self.assertEqual(len(rows), 2)
        self.assertEqual(rows, [("Ada",), ("Bob",)])

    def test_fetch_many_validation(self):
        with self.assertRaises(TypeError):
            fetch_many(self.conn, "SELECT 1", "2")  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            fetch_many(self.conn, "SELECT 1", -1)

    def test_executemany(self):
        executemany(
            self.conn,
            "INSERT INTO users (name, score) VALUES (?, ?)",
            [("Ada", 92.5), ("Bob", 87.0)],
        )
        rows = fetch_all(self.conn, "SELECT name FROM users ORDER BY name")
        self.assertEqual(rows, [("Ada",), ("Bob",)])

    def test_executemany_validation(self):
        with self.assertRaises(TypeError):
            executemany(self.conn, "SELECT 1", "not-a-list")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            executemany(self.conn, "SELECT 1", [123])  # type: ignore[arg-type]

    def test_query_dicts(self):
        insert_row(self.conn, "users", ["name", "score"], ["Ada", 92.5])
        rows = query(self.conn, "SELECT id, name, score FROM users")
        self.assertEqual(rows, [{"id": 1, "name": "Ada", "score": 92.5}])

    def test_query_no_rows(self):
        rows = query(self.conn, "SELECT name FROM users WHERE id = ?", [999])
        self.assertEqual(rows, [])

    def test_table_exists(self):
        self.assertTrue(table_exists(self.conn, "users"))
        self.assertFalse(table_exists(self.conn, "nonexistent"))

    def test_table_exists_validation(self):
        with self.assertRaises(TypeError):
            table_exists(self.conn, 1)  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            table_exists(self.conn, "")

    def test_create_table_validation(self):
        with self.assertRaises(TypeError):
            create_table(self.conn, 1, "x TEXT")  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            create_table(self.conn, "", "x TEXT")
        with self.assertRaises(ValueError):
            create_table(self.conn, "t", "   ")

    def test_execute_validation(self):
        with self.assertRaises(TypeError):
            execute(None, "SELECT 1")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            execute(self.conn, 1)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            execute(self.conn, "SELECT 1", "params")  # type: ignore[arg-type]


if __name__ == "__main__":
    unittest.main()
TEST_SQLITE3_UTILS

# --- signal_utils.py ---
cat > "$OUTPUT_DIR/signal_utils.py" <<'SIGNALUTILS'
"""Signal utilities (wrapping :mod:`signal`).

This module provides helpers for working with POSIX signals using the
standard library :mod:`signal` module. All functions validate inputs and
raise :class:`TypeError` or :class:`ValueError` for invalid arguments where
applicable.
"""

from __future__ import annotations

import signal
from typing import Any, Callable, Dict, List

__all__: list[str] = [
    "alarm",
    "get_handler",
    "get_signal_name",
    "interrupt_handler",
    "is_valid_signal",
    "pause",
    "register_handler",
    "register_int_handler",
    "register_term_handler",
    "set_handler",
    "signal_info",
    "signal_names",
    "suspend_handler",
    "unregister_handler",
]


def is_valid_signal(sig: Any) -> bool:
    """Return True if ``sig`` is a valid signal number on this platform."""
    if not isinstance(sig, int):
        return False
    try:
        signal.Signals(sig)
    except ValueError:
        return False
    return True


def get_signal_name(sig: int) -> str:
    """Return the name of the signal identified by ``sig``.

    Args:
        sig: Signal number.

    Returns:
        Signal name (e.g., ``"SIGINT"``).

    Raises:
        TypeError: If ``sig`` is not an int.
        ValueError: If ``sig`` is not a valid signal number.
    """
    if not isinstance(sig, int):
        raise TypeError("sig must be an int")
    try:
        return signal.Signals(sig).name
    except ValueError as exc:
        raise ValueError(f"invalid signal number: {sig!r}") from exc


def signal_names() -> List[str]:
    """Return a sorted list of all signal names available on this platform."""
    return sorted(s.name for s in signal.Signals)


def get_handler(sig: int) -> Any:
    """Return the current handler for ``sig``.

    Args:
        sig: Signal number.

    Returns:
        The current handler (callable, ``signal.SIG_DFL``, or
        ``signal.SIG_IGN``).

    Raises:
        TypeError: If ``sig`` is not an int.
        ValueError: If ``sig`` is not a valid signal number.
    """
    if not isinstance(sig, int):
        raise TypeError("sig must be an int")
    if not is_valid_signal(sig):
        raise ValueError(f"invalid signal number: {sig!r}")
    return signal.getsignal(sig)


def set_handler(sig: int, handler: Any) -> None:
    """Set the handler for ``sig``.

    Args:
        sig: Signal number.
        handler: A callable, ``signal.SIG_DFL``, or ``signal.SIG_IGN``.

    Raises:
        TypeError: If ``sig`` is not an int.
        ValueError: If ``sig`` is not a valid signal number.
    """
    if not isinstance(sig, int):
        raise TypeError("sig must be an int")
    if not is_valid_signal(sig):
        raise ValueError(f"invalid signal number: {sig!r}")
    signal.signal(sig, handler)


def register_handler(sig: int, handler: Callable[[int, Any], Any]) -> None:
    """Register a callable ``handler`` for ``sig``.

    Args:
        sig: Signal number.
        handler: Callable invoked with (signum, frame) when the signal fires.

    Raises:
        TypeError: If ``sig`` is not an int or ``handler`` is not callable.
        ValueError: If ``sig`` is not a valid signal number.
    """
    if not isinstance(sig, int):
        raise TypeError("sig must be an int")
    if not callable(handler):
        raise TypeError("handler must be callable")
    if not is_valid_signal(sig):
        raise ValueError(f"invalid signal number: {sig!r}")
    signal.signal(sig, handler)


def register_int_handler(handler: Callable[[int, Any], Any]) -> None:
    """Register ``handler`` for ``SIGINT`` (KeyboardInterrupt).

    Raises:
        TypeError: If ``handler`` is not callable.
    """
    if not callable(handler):
        raise TypeError("handler must be callable")
    signal.signal(signal.SIGINT, handler)


def register_term_handler(handler: Callable[[int, Any], Any]) -> None:
    """Register ``handler`` for ``SIGTERM``.

    Raises:
        TypeError: If ``handler`` is not callable.
    """
    if not callable(handler):
        raise TypeError("handler must be callable")
    signal.signal(signal.SIGTERM, handler)


def interrupt_handler(signum: int, frame: Any) -> None:
    """Default ``SIGINT`` handler that raises :class:`KeyboardInterrupt`."""
    raise KeyboardInterrupt


def suspend_handler(signum: int, frame: Any) -> None:
    """No-op signal handler used to suppress or ignore a signal."""
    return None


def unregister_handler(sig: int) -> None:
    """Reset the handler for ``sig`` to its default (``SIG_DFL``).

    Args:
        sig: Signal number.

    Raises:
        TypeError: If ``sig`` is not an int.
        ValueError: If ``sig`` is not a valid signal number.
    """
    if not isinstance(sig, int):
        raise TypeError("sig must be an int")
    if not is_valid_signal(sig):
        raise ValueError(f"invalid signal number: {sig!r}")
    signal.signal(sig, signal.SIG_DFL)


def alarm(seconds: int) -> int:
    """Schedule a ``SIGALRM`` to be delivered after ``seconds`` seconds.

    Args:
        seconds: Number of seconds before the signal is delivered.

    Returns:
        The number of seconds remaining on any previously scheduled alarm.

    Raises:
        TypeError: If ``seconds`` is not an int.
        ValueError: If ``seconds`` is negative.
    """
    if not isinstance(seconds, int):
        raise TypeError("seconds must be an int")
    if seconds < 0:
        raise ValueError("seconds must be non-negative")
    return signal.alarm(seconds)


def pause() -> None:
    """Wait for the next signal to be delivered."""
    signal.pause()


def signal_info() -> Dict[str, Any]:
    """Return a dictionary with signal-related information.

    Returns:
        Dictionary with signal names, the SIGINT handler, and whether
        SIGALRM is available.
    """
    return {
        "names": signal_names(),
        "sigint_handler": signal.getsignal(signal.SIGINT),
        "alarm_available": hasattr(signal, "alarm"),
    }
SIGNALUTILS

# --- tests/test_signal_utils.py ---
cat > "$OUTPUT_DIR/tests/test_signal_utils.py" <<'TEST_SIGNAL_UTILS'
"""Unit tests for signal_utils module."""

import signal
import unittest

from signal_utils import (
    alarm,
    get_handler,
    get_signal_name,
    interrupt_handler,
    is_valid_signal,
    pause,
    register_handler,
    register_int_handler,
    register_term_handler,
    set_handler,
    signal_info,
    signal_names,
    suspend_handler,
    unregister_handler,
)

# Use SIGUSR1 when available (POSIX), otherwise fall back to SIGINT so the
# tests run on platforms with a reduced signal set.
_TEST_SIGNAL = signal.SIGUSR1 if hasattr(signal, "SIGUSR1") else signal.SIGINT


class TestSignalUtils(unittest.TestCase):
    def test_is_valid_signal(self):
        self.assertTrue(is_valid_signal(signal.SIGINT))
        self.assertFalse(is_valid_signal("SIGINT"))
        self.assertFalse(is_valid_signal(999999))
        self.assertFalse(is_valid_signal(None))

    def test_get_signal_name(self):
        self.assertEqual(get_signal_name(signal.SIGINT), "SIGINT")
        with self.assertRaises(TypeError):
            get_signal_name("SIGINT")  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            get_signal_name(999999)

    def test_signal_names(self):
        names = signal_names()
        self.assertIsInstance(names, list)
        self.assertIn("SIGINT", names)
        self.assertEqual(names, sorted(names))

    def test_get_handler(self):
        handler = get_handler(signal.SIGINT)
        self.assertIn(handler, (signal.SIG_DFL, signal.SIG_IGN, signal.default_int_handler))

    def test_set_handler_round_trip(self):
        original = signal.getsignal(_TEST_SIGNAL)
        try:
            set_handler(_TEST_SIGNAL, suspend_handler)
            self.assertIs(signal.getsignal(_TEST_SIGNAL), suspend_handler)
        finally:
            signal.signal(_TEST_SIGNAL, original)

    def test_register_int_handler(self):
        original = signal.getsignal(signal.SIGINT)
        try:
            register_int_handler(suspend_handler)
            self.assertIs(signal.getsignal(signal.SIGINT), suspend_handler)
        finally:
            signal.signal(signal.SIGINT, original)

    def test_register_term_handler(self):
        original = signal.getsignal(signal.SIGTERM)
        try:
            register_term_handler(suspend_handler)
            self.assertIs(signal.getsignal(signal.SIGTERM), suspend_handler)
        finally:
            signal.signal(signal.SIGTERM, original)

    def test_register_handler_type_errors(self):
        with self.assertRaises(TypeError):
            register_handler("SIGINT", suspend_handler)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            register_handler(signal.SIGINT, "not callable")  # type: ignore[arg-type]

    def test_interrupt_handler(self):
        with self.assertRaises(KeyboardInterrupt):
            interrupt_handler(signal.SIGINT, None)

    def test_suspend_handler(self):
        self.assertIsNone(suspend_handler(signal.SIGINT, None))

    def test_alarm(self):
        self.assertEqual(alarm(0), 0)

    def test_alarm_type_errors(self):
        with self.assertRaises(TypeError):
            alarm("5")  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            alarm(-1)

    def test_pause_is_callable(self):
        self.assertTrue(callable(pause))

    def test_signal_info(self):
        info = signal_info()
        self.assertIsInstance(info, dict)
        self.assertIn("names", info)
        self.assertIn("sigint_handler", info)
        self.assertIn("alarm_available", info)

    def test_unregister_handler(self):
        original = signal.getsignal(_TEST_SIGNAL)
        try:
            unregister_handler(_TEST_SIGNAL)
            self.assertIs(signal.getsignal(_TEST_SIGNAL), signal.SIG_DFL)
        finally:
            signal.signal(_TEST_SIGNAL, original)


if __name__ == "__main__":
    unittest.main()
TEST_SIGNAL_UTILS
